import random
import struct
from typing import List, Tuple

# This script generates consensus-serialized Bitcoin transactions (legacy/segwit/taproot-capable shapes)
# tailored for btck_transaction_create fuzzing. It aims to produce validly formatted tx bytes with
# varied features while staying within 4096 bytes.

# Utilities for Bitcoin varint encoding

def _varint(n: int) -> bytes:
    if n < 0xfd:
        return struct.pack('<B', n)
    if n <= 0xffff:
        return b"\xfd" + struct.pack('<H', n)
    if n <= 0xffffffff:
        return b"\xfe" + struct.pack('<I', n)
    return b"\xff" + struct.pack('<Q', n)

# Script building helpers

def _push_data(data: bytes) -> bytes:
    ln = len(data)
    if ln <= 75:
        return struct.pack('<B', ln) + data
    elif ln <= 255:
        return b"\x4c" + struct.pack('<B', ln) + data  # OP_PUSHDATA1
    elif ln <= 65535:
        return b"\x4d" + struct.pack('<H', ln) + data  # OP_PUSHDATA2
    else:
        return b"\x4e" + struct.pack('<I', ln) + data  # OP_PUSHDATA3 (unlikely here)

# Common standard scripts

def script_p2pkh(pubkey_hash: bytes) -> bytes:
    # OP_DUP OP_HASH160 <20-byte> OP_EQUALVERIFY OP_CHECKSIG
    assert len(pubkey_hash) == 20
    return b"\x76\xa9" + _push_data(pubkey_hash) + b"\x88\xac"

def script_p2sh(script_hash: bytes) -> bytes:
    # OP_HASH160 <20-byte> OP_EQUAL
    assert len(script_hash) == 20
    return b"\xa9" + _push_data(script_hash) + b"\x87"

def script_p2wpkh(pubkey_hash: bytes) -> bytes:
    # 0 <20>
    assert len(pubkey_hash) == 20
    return b"\x00" + _push_data(pubkey_hash)

def script_p2wsh(script_hash: bytes) -> bytes:
    # 0 <32>
    assert len(script_hash) == 32
    return b"\x00" + _push_data(script_hash)

def script_p2tr(xonly_pubkey: bytes) -> bytes:
    # OP_1 <32-byte xonly key>
    assert len(xonly_pubkey) == 32
    return b"\x51" + _push_data(xonly_pubkey)

# Input scriptSig templates

def scriptsig_p2pkh(sig_len: int, pub_len: int, rng: random.Random) -> bytes:
    sig = bytes(rng.getrandbits(8) for _ in range(max(1, sig_len)))
    pub = bytes(rng.getrandbits(8) for _ in range(max(33, pub_len)))
    return _push_data(sig) + _push_data(pub)

def scriptsig_p2sh_redeem_p2wpkh(pubkey_hash: bytes) -> bytes:
    redeem = script_p2wpkh(pubkey_hash)
    return _push_data(redeem)

