    vin_list = []
    witness_list = []

    for _ in range(n_in):
        kind = rng.choices(['native-wpkh', 'native-wsh', 'native-tr', 'legacy-p2sh-wpkh'],
                           weights=[3, 1, 2, 2], k=1)[0]
        if kind == 'legacy-p2sh-wpkh':
            vin, is_wit, _ss = _make_legacy_input(rng)
            vin_list.append(vin)
            witness_list.append(_make_witness_for_input(True, rng))
        elif kind == 'native-wpkh':
            vin, wit = _make_native_witness_input(rng, 'wpkh')
            vin_list.append(vin)
            witness_list.append(wit)
        elif kind == 'native-wsh':
            vin, wit = _make_native_witness_input(rng, 'wsh')
            vin_list.append(vin)
            witness_list.append(wit)
        else:  # native-tr
            vin, wit = _make_native_witness_input(rng, 'tr')
            vin_list.append(vin)
            witness_list.append(wit)

    vout_parts = []
    for _ in range(n_out):
        vout_parts.append(_make_output(rng)[0])

    locktime = rng.choice([0, rng.randrange(0, 500000000), 0xffffffff])

    # Assemble witness transaction per BIP144: version | 0x00 0x01 | vin | vout | witnesses | locktime
    base = struct.pack('<i', version) + marker + flag
    base += _varint(n_in) + b"".join(vin_list)
    base += _varint(n_out) + b"".join(vout_parts)
    for wit in witness_list:
        base += wit
    base += struct.pack('<I', locktime)
    return base

def _maybe_coinbase_tx(rng: random.Random) -> bytes:
    # Construct a coinbase transaction (single input with prevout=0x00..00:0xffffffff and arbitrary coinbase script)
    version = rng.choice([1, 2])
    # coinbase input
    prev_txid = b"\x00" * 32
    vout = 0xffffffff
    coinbase_script = _rand_bytes(rng, rng.randrange(2, 100))
    sequence = 0xffffffff
    vin = prev_txid + struct.pack('<I', vout) + _varint(len(coinbase_script)) + coinbase_script + struct.pack('<I', sequence)
    n_in = 1
    n_out = rng.randrange(1, 3)
    vouts = [_make_output(rng)[0] for _ in range(n_out)]
    locktime = rng.choice([0, rng.randrange(0, 500000000)])
    return struct.pack('<i', version) + _varint(n_in) + vin + _varint(n_out) + b"".join(vouts) + struct.pack('<I', locktime)


def _choose_tx(rng: random.Random) -> bytes:
    choice = rng.choices(['legacy', 'segwit', 'coinbase'], weights=[5, 4, 1], k=1)[0]
    if choice == 'legacy':
        return _build_legacy_tx(rng)
    if choice == 'coinbase':
        return _maybe_coinbase_tx(rng)
    return _build_segwit_tx(rng)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Small chance to return empty buffer to exercise chosen_len==0 + NULL
    if rng.random() < 0.05:
        return b""

    # Build between 1 and 3 transactions concatenated; FUZZ_PARAM_STR can be any bytes, but we
    # prefer valid single tx. However, concatenations can still be useful; the fuzzer may slice.
    count = 1 if rng.random() < 0.8 else rng.randrange(2, 4)
    parts: List[bytes] = []
    for _ in range(count):
        tx = _choose_tx(rng)
        parts.append(tx)
        if sum(len(p) for p in parts) > 3500:
            break
    out = b"".join(parts)
    # Ensure under 4096
    return out[:4096]

import random
from typing import List

def _varint(n: int) -> bytes:
    if n < 0xfd:
        return bytes([n])
    elif n <= 0xffff:
        return b"\xfd" + n.to_bytes(2, 'little')
    elif n <= 0xffffffff:
        return b"\xfe" + n.to_bytes(4, 'little')
    else:
        return b"\xff" + n.to_bytes(8, 'little')

# Helpers to build standard script templates (scriptPubKey locking scripts)

def p2pkh(hash160: bytes) -> bytes:
    # OP_DUP OP_HASH160 PUSHDATA(20) <hash160> OP_EQUALVERIFY OP_CHECKSIG
    assert len(hash160) == 20
    return bytes([0x76, 0xa9, 0x14]) + hash160 + bytes([0x88, 0xac])


def p2sh(hash160: bytes) -> bytes:
    # OP_HASH160 PUSHDATA(20) <hash160> OP_EQUAL
    assert len(hash160) == 20
    return bytes([0xa9, 0x14]) + hash160 + bytes([0x87])


def p2wpkh(program: bytes) -> bytes:
    # OP_0 PUSHDATA(20) <program>
    assert len(program) == 20
    return bytes([0x00, 0x14]) + program


def p2wsh(program: bytes) -> bytes:
    # OP_0 PUSHDATA(32) <program>
    assert len(program) == 32
    return bytes([0x00, 0x20]) + program


def p2tr(xonly_pubkey: bytes) -> bytes:
    # OP_1 PUSHDATA(32) <xonly_pubkey>
    assert len(xonly_pubkey) == 32
    return bytes([0x51, 0x20]) + xonly_pubkey


def op_return(data: bytes) -> bytes:
    # OP_RETURN (0x6a) followed by canonical push of data (<= 80 typical, but any pushdata is allowed in bytes domain)
    n = len(data)
    if n <= 75:
        return bytes([0x6a, n]) + data
    elif n <= 255:
        return bytes([0x6a, 0x4c, n]) + data
    elif n <= 65535:
        return bytes([0x6a, 0x4d]) + n.to_bytes(2, 'little') + data
    else:
        return bytes([0x6a, 0x4e]) + n.to_bytes(4, 'little') + data


def small_multisig(m: int, n: int, pubkeys: List[bytes]) -> bytes:
    # Minimal bare multisig: OP_m <pubkeys> OP_n OP_CHECKMULTISIG
    assert 1 <= m <= n <= 16
    assert len(pubkeys) == n
    out = bytearray()
    out.append(0x50 + m)  # OP_1..OP_16
    for pk in pubkeys:
        # push 33-byte compressed pubkeys (len could vary but keep canonical)
        out.append(len(pk))
        out.extend(pk)
    out.append(0x50 + n)  # OP_1..OP_16
    out.append(0xae)      # OP_CHECKMULTISIG
    return bytes(out)


def random_bytes(rng: random.Random, n: int) -> bytes:
    return bytes(rng.getrandbits(8) for _ in range(n))


def _choose_template(rng: random.Random) -> bytes:
    # Weighted selection of common and edge-case scripts
    choices = [
        "empty",
        "p2pkh",
        "p2sh",
        "p2wpkh",
        "p2wsh",
        "p2tr",
        "nulldata_small",
        "nulldata_large",
        "bare_multisig_1of1",
        "bare_multisig_2of3",
        "random_pushes",
    ]
    kind = rng.choices(choices, weights=[2, 15, 8, 8, 6, 6, 6, 2, 4, 4, 7], k=1)[0]

    if kind == "empty":
        return b""  # valid empty script
    if kind == "p2pkh":
        return p2pkh(random_bytes(rng, 20))
    if kind == "p2sh":
        return p2sh(random_bytes(rng, 20))
    if kind == "p2wpkh":
        return p2wpkh(random_bytes(rng, 20))
    if kind == "p2wsh":
        return p2wsh(random_bytes(rng, 32))
    if kind == "p2tr":
        return p2tr(random_bytes(rng, 32))
    if kind == "nulldata_small":
        n = rng.randrange(0, 81)  # typical relay limit
        return op_return(random_bytes(rng, n))
    if kind == "nulldata_large":
        # Larger OP_RETURN to exercise PUSHDATA encodings but keep <= 1024
        n = rng.randrange(81, 512)
        return op_return(random_bytes(rng, n))
    if kind == "bare_multisig_1of1":
        pk = bytes([0x02]) + random_bytes(rng, 32)  # 33-byte compressed
        return small_multisig(1, 1, [pk])
    if kind == "bare_multisig_2of3":
        pubkeys = []
        for _ in range(3):
            pubkeys.append(bytes([rng.choice([0x02, 0x03])]) + random_bytes(rng, 32))
        return small_multisig(2, 3, pubkeys)
    if kind == "random_pushes":
        # Build a sequence of random push operations mixed with small ops
        out = bytearray()
        count = rng.randrange(1, 10)
        for _ in range(count):
            t = rng.randrange(0, 5)
            if t == 0:
                # small immediate push (0..75)
                n = rng.randrange(0, 76)
                out.append(n)
                out.extend(random_bytes(rng, n))
            elif t == 1:
                # PUSHDATA1
                n = rng.randrange(0, 256)
                out.extend([0x4c, n])
                out.extend(random_bytes(rng, n))
            elif t == 2:
                # PUSHDATA2
                n = rng.randrange(0, 300)  # keep modest
                out.extend([0x4d])
                out.extend(n.to_bytes(2, 'little'))
                out.extend(random_bytes(rng, n))
            elif t == 3:
                # Small opcodes like OP_DUP/OP_EQUAL/OP_VERIFY etc.
                out.append(rng.choice([0x75, 0x76, 0xa9, 0x88, 0x87, 0xac, 0x6a]))
            else:
                # Numeric OP_0..OP_16
                if rng.random() < 0.2:
                    out.append(0x00)
                else:
                    out.append(0x51 + rng.randrange(0, 16))
        return bytes(out)
    # Fallback
    return b""


def _maybe_concatenate(rng: random.Random, base: bytes) -> bytes:
    # Occasionally append another small valid snippet to exercise longer scripts
    if len(base) > 2000:
        return base
    if rng.random() < 0.3:
        extra = _choose_template(rng)
        # Ensure total stays under 4096
        max_extra = max(0, 4096 - len(base))
        if len(extra) > max_extra:
            extra = extra[:max_extra]
        return base + extra
    return base


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Build a scriptPubKey bytes buffer suitable for btck_script_pubkey_create fuzzer stub
    script = _choose_template(rng)
    script = _maybe_concatenate(rng, script)
    # Ensure final size limit
    if len(script) > 4096:
        script = script[:4096]
    return script
